import subprocess, sys, tempfile, json, collections
BIN = "/tmp/lyp-cap-re-matcher/bin/lypning-l"
rows = json.load(open(sys.argv[1]))
limit = int(sys.argv[2]) if len(sys.argv) > 2 else 20
bad = 0; refused = collections.Counter(); ok = 0; shown = 0
d = tempfile.mkdtemp()
for i, p in enumerate(rows):
    g = subprocess.run([BIN, "-c", p], capture_output=True, text=True, cwd=d, timeout=120)
    if g.returncode == 90:
        refused[g.stderr.strip()[len("lypning-l: unsupported: "):][:90]] += 1
        if g.stdout != "" or "\n" in g.stderr.strip(): print("DIRTY %d: %r" % (i, p)); bad += 1
        continue
    r = subprocess.run([sys.executable, "-W", "ignore", "-c", p], capture_output=True, text=True, cwd=d, timeout=120)
    if (g.stdout, g.returncode) != (r.stdout, r.returncode):
        bad += 1
        if shown < limit:
            shown += 1
            print("MISMATCH %d: %s" % (i, p.replace("\n", " | ")))
            for a, b in zip(g.stdout.splitlines(), r.stdout.splitlines()):
                if a != b: print("   lyp: %s\n   cpy: %s" % (a[:250], b[:250]))
            if g.returncode != r.returncode: print("   exit %d vs %d  %s" % (g.returncode, r.returncode, g.stderr.strip()[-140:]))
    else: ok += 1
print("rows=%d ok=%d mismatch=%d refused=%d" % (len(rows), ok, bad, sum(refused.values())))
for k, v in refused.most_common(15): print("  %5d %s" % (v, k))

