import json, re, collections
p="src/lypning/assets/corpus/corpus.jsonl"
rows=[]
for line in open(p, encoding="utf-8"):
    line=line.strip()
    if not line: continue
    try: d=json.loads(line)
    except Exception: continue
    rows.append((d.get("program") or "", d.get("count") or 1))

STR=re.compile(r'("""|\'\'\'|"|\').*?\1', re.S)
NUM=re.compile(r'\b\d+(\.\d+)?\b')
WS=re.compile(r'[ \t]+')
def shape(s):
    s=STR.sub('"S"', s)
    s=NUM.sub('N', s)
    s=WS.sub(' ', s)
    return s.strip()

import ast
def feat(s):
    try: t=ast.parse(s)
    except SyntaxError: return ("<syntax>",)
    imps=set(); names=collections.Counter()
    for n in ast.walk(t):
        if isinstance(n, ast.Import):
            for a in n.names: imps.add(a.name.split(".")[0])
        elif isinstance(n, ast.ImportFrom):
            if n.module: imps.add(n.module.split(".")[0])
        elif isinstance(n, ast.Attribute): names[n.attr]+=1
        elif isinstance(n, ast.Name): names[n.id]+=1
        else: names[type(n).__name__]+=1
    return (tuple(sorted(imps)), tuple(sorted(names)))

shapes=collections.Counter(); feats=collections.Counter()
for s,c in rows:
    shapes[shape(s)]+=c
    feats[feat(s)]+=c
tot=sum(c for _,c in rows)
print("invocations:", tot, "distinct programs:", len(rows))
print("distinct shapes (literals erased):", len(shapes))
print("distinct feature keys (imports+node/name set):", len(feats))
print("invocations covered by a shape seen >1x: %.1f%%" % (100*sum(v for v in shapes.values() if v>1)/tot))
print("invocations covered by a featkey seen >1x: %.1f%%" % (100*sum(v for v in feats.values() if v>1)/tot))
print("mean programs per featkey: %.2f" % (len(rows)/len(feats)))

