/// [`bind`] is on the hottest argument-reading calls the interpreter has.
#[cold]
#[inline(never)]
fn given_twice(func: &str, name: &str, pos: usize) -> LypningError {
    type_err(format!(
        "argument for {func}() given by name ('{name}') and position ({})",
        pos + 1
    ))
}

