#!/usr/bin/env python3
"""Differential runner: lypning-l vs cpython, per-engine temp cwd, identical trees."""
from __future__ import annotations
import os, subprocess, sys, shutil, tempfile, json

L = "/tmp/lyp-adv-glob2/bin/lypning-l"
PY = sys.executable
ROOT = "/tmp/lyp-adv-glob2/runs"

def build_tree(d, setup):
    os.makedirs(d, exist_ok=True)
    if setup:
        subprocess.run(["/bin/sh", "-c", setup], cwd=d, check=True,
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

def run(cmd, cwd):
    p = subprocess.run(cmd, cwd=cwd, capture_output=True)
    return p.returncode, p.stdout, p.stderr

def snapshot(d):
    out = []
    for r, ds, fs in os.walk(d):
        ds.sort(); fs.sort()
        rel = os.path.relpath(r, d)
        for x in sorted(ds)+sorted(fs):
            out.append(os.path.join(rel, x))
    return sorted(out)

def one(idx, prog, setup="", check_disk=False):
    base = os.path.join(ROOT, "t%04d" % idx)
    shutil.rmtree(base, ignore_errors=True)
    a = os.path.join(base, "lyp"); b = os.path.join(base, "cpy")
    build_tree(a, setup); build_tree(b, setup)
    pre = snapshot(a)
    rc1, o1, e1 = run([L, "-c", prog], a)
    post = snapshot(a)
    rc2, o2, e2 = run([PY, "-c", prog], b)
    res = dict(i=idx, prog=prog, setup=setup, lrc=rc1, lout=o1.decode('utf8','replace'),
               lerr=e1.decode('utf8','replace'), crc=rc2, cout=o2.decode('utf8','replace'),
               cerr=e2.decode('utf8','replace'), disk_changed=(pre!=post),
               added=[x for x in post if x not in pre])
    # classify
    if rc1 == 90:
        lines = e1.decode('utf8','replace').splitlines()
        ok = (o1 == b"" and len(lines) == 1 and lines[0].startswith("lypning-l: unsupported: "))
        res['verdict'] = "REFUSE-OK" if ok else "REFUSE-BAD"
        if check_disk and res['disk_changed']:
            res['verdict'] = "REFUSE-DIRTY"
    elif (rc1, o1, e1) == (rc2, o2, e2):
        res['verdict'] = "MATCH"
    else:
        res['verdict'] = "MISMATCH"
    return res

def main():
    cases = json.load(open(sys.argv[1]))
    shutil.rmtree(ROOT, ignore_errors=True); os.makedirs(ROOT, exist_ok=True)
    bad = []
    counts = {}
    for i, c in enumerate(cases):
        if isinstance(c, str): c = {"prog": c}
        r = one(i, c["prog"], c.get("setup",""), c.get("check_disk", False))
        counts[r['verdict']] = counts.get(r['verdict'],0)+1
        if r['verdict'] not in ("MATCH","REFUSE-OK"):
            bad.append(r)
        if c.get("show"): bad.append(r)
    print(json.dumps({"counts":counts,"bad":bad}, indent=1))

main()

