/// The order rule is about those two and no others: `escape` and `has_magic`
/// are pure string algebra and carry no order to show.
fn glob_call(func: &Expr, req: &Requirements) -> Option<bool> {
    match glob_func(func, req)? {
        "glob" => Some(false),
        "iglob" => Some(true),
        _ => None,
    }
