rows=[json.loads(l) for l in open('class_progs.jsonl')]
SERVED={'sys','os','os.path','posixpath','io','json','random','collections','pathlib','re'}
n_clean=0
for i,r in enumerate(rows):
    p=r['program']
    try: t=ast.parse(p)
    except SyntaxError: print(i,'PARSE-ERR'); continue
    mods=set()
    for nd in ast.walk(t):
        if isinstance(nd,ast.Import): mods|={a.name.split('.')[0] for a in nd.names}
        elif isinstance(nd,ast.ImportFrom) and nd.module: mods.add(nd.module.split('.')[0])
    other=sorted(m for m in mods if m not in SERVED)
    haspath = 'sys.path' in p
    print('%2d %-10s mods_unserved=%-40s sys.path=%s' % (i, r['id'][:8], ','.join(other) or '-', haspath))
    if not other and not haspath: n_clean+=1
