from lypning import conformance, corpus
entries = corpus.load_default()
byid = {e.id: e for e in entries}

def verdicts(engine, binenv=None):
    old = dict(os.environ)
    if binenv: os.environ.update(binenv)
    try:
        rep = conformance.run(entries, engines=[engine])
    finally:
        os.environ.clear(); os.environ.update(old)
    er = rep.engines[engine]
    return {v.entry_id: (v.verdict, getattr(v, "kind", "")) for v in er.verdicts}

new = verdicts("lypning-l")
base = verdicts("lypning-l", {"LYPNING_L_BIN": "/tmp/lyp-base-target-l/release/lypning"})
gained, lost, changed = [], [], []
for k in set(base) | set(new):
    b, n = base.get(k), new.get(k)
    if b == n: continue
    if b and n and b[0] != "MATCH" and n[0] == "MATCH": gained.append((k, b, n))
    elif b and n and b[0] == "MATCH" and n[0] != "MATCH": lost.append((k, b, n))
    else: changed.append((k, b, n))
print("GAINED (not-MATCH -> MATCH):", len(gained))
for k, b, n in sorted(gained):
    print("   +", k, b, "->", n, "|", byid[k].program[:70].replace("\n",";"))
print("LOST (MATCH -> not-MATCH):", len(lost))
for k, b, n in sorted(lost):
    print("   -", k, b, "->", n, "|", byid[k].program[:70].replace("\n",";"))
print("OTHER CHANGES:", len(changed))
for k, b, n in sorted(changed)[:20]:
    print("   ~", k, b, "->", n, "|", byid[k].program[:70].replace("\n",";"))

