    let Some(Expr::Str(p)) = re_call_of(func, args, req) else {
        return;
    };
    if let Err(e) = crate::re::precompile(p) {
        if let crate::err::ErrKind::Unsupported { kind, detail } = e.kind() {
            req.block(kind, detail.clone());
        }
    }
}

