    // `from math import …` is not resolved here and keeps the runtime backstop.
    let Expr::Attr(base, name) = func else { return };
    if !matches!(resolve_module(base, &req.aliases), Some(crate::value::Value::Module("math"))) {
        return;
    }
    if !crate::math::is_func(name) {
        // `math.fmod(…)` — the `Expr::Attr` arm blocks it as `module-attr`
        // whether or not it is called, and this must not displace that row.
        return;
