        return;
    }
    let as_args: Vec<crate::math::Arg> = args.iter().map(math_arg).collect();
    if let Err(e) = crate::math::check(name, &as_args) {
        if let crate::err::ErrKind::Unsupported { kind, detail } = e.kind() {
            req.block(kind, detail.clone());
        }
    }
