/// literal of another type is the TypeError CPython raises; everything else is
/// a value only the runtime will know.
#[cfg(feature = "cap-math")]
fn math_arg(e: &Expr) -> crate::math::Arg {
    use crate::math::Arg;
    match e {
        Expr::Int(i) => Arg::Int(*i),
        Expr::Float(f) => Arg::Float(*f),
        Expr::True => Arg::Int(1),
        Expr::False => Arg::Int(0),
        // `math.factorial(-1)` is written as a negation of a literal, and it is
        // the shape the domain rule most needs to see.
        Expr::Un(UnOp::Neg, inner) => match math_arg(inner) {
            Arg::Int(i) => i.checked_neg().map(Arg::Int).unwrap_or(Arg::Unknown),
            Arg::Float(f) => Arg::Float(-f),
            _ => Arg::Unknown,
