        Expr::Un(UnOp::Pos, inner) => math_arg(inner),
        Expr::Str(_) | Expr::Bytes(_) | Expr::None | Expr::List(_) | Expr::Dict(_)
        | Expr::Tuple(_) | Expr::Set(_) => Arg::NotNum,
        _ => Arg::Unknown,
    }
}

