import subprocess
def syms(p):
    out=subprocess.run(["nm","-n","-U","--print-size" if False else "-U",p],capture_output=True,text=True).stdout
    rows=[]
    for l in out.splitlines():
        parts=l.split(None,2)
        if len(parts)>=3 and parts[1] in "tTsSdD":
            try: rows.append((int(parts[0],16),parts[2]))
            except ValueError: pass
    rows.sort()
    d={}
    for i,(a,n) in enumerate(rows):
        end = rows[i+1][0] if i+1<len(rows) else a
        d[n]=d.get(n,0)+max(0,end-a)
    return d
