"""Second sweep: deeper nesting, richer bodies, alternation, several groups."""
from __future__ import annotations
import itertools, subprocess, sys, tempfile, os

Q = ["", "*", "*?", "+", "+?", "?", "??", "{1,2}", "{1,2}?", "{2,3}", "{2,3}?",
     "{2}", "{2}?", "{0,2}", "{1,}", "{1,}?", "{2,}", "{3,4}?"]
BODIES = ["a", "a|b", "ab", "a|", "(?:a|bb)", "[ab]", "\\w", "a?b"]
SUBJ = ["", "a", "b", "ab", "ba", "aa", "bb", "aab", "abb", "aba", "abab", "aaab", "abc", "x"]

def gen():
    out = []
    # 2-deep: ( body Q1 ) Q2   and non-capturing, plus a tail
    for b, q1, q2, g, t in itertools.product(BODIES, Q, Q, ["(%s)", "(?:%s)"], ["", "b", "$", "c"]):
        out.append(g % ("(?:%s)%s" % (b, q1)) + q2 + t)
    # 3-deep with a group at each level
    for q1, q2, q3 in itertools.product(Q, repeat=3):
        out.append("((a%s)%s)%s" % (q1, q2, q3))
        out.append("((?:(a%s)%s)%s)b" % (q1, q2, q3))
    # two groups side by side inside a counted repeat
    for q1, q2, q3 in itertools.product(Q, repeat=3):
        out.append("(?:(a%s)(b%s))%s" % (q1, q2, q3))
    seen, uniq = set(), []
    for p in out:
        if p not in seen:
            seen.add(p); uniq.append(p)
    return uniq

PROBE = r'''
import re
def one(p, s):
    try: m = re.search(p, s)
    except Exception as e: return "E:" + type(e).__name__
    r = [None if m is None else (m.span(), m.groups(), [m.span(i) for i in range(1, (m.re.groups or 0) + 1)])]
    for f in (lambda: re.findall(p, s), lambda: re.split(p, s),
              lambda: re.sub(p, "<\\1>" if re.compile(p).groups else "<>", s),
              lambda: [(x.span(), x.groups()) for x in re.finditer(p, s)],
              lambda: (lambda mm: None if mm is None else (mm.span(), mm.groups()))(re.match(p, s)),
              lambda: (lambda mm: None if mm is None else (mm.span(), mm.groups()))(re.fullmatch(p, s))):
        try: r.append(f())
        except Exception as e: r.append("E:" + type(e).__name__)
    return r
PAT = __PATS__
SUB = __SUBJ__
for p in PAT:
    for s in SUB:
        print(repr(p), repr(s), one(p, s), flush=True)
'''

def run(exe, pats, subj):
    prog = PROBE.replace("__PATS__", repr(pats)).replace("__SUBJ__", repr(subj))
    with tempfile.TemporaryDirectory() as d:
        return subprocess.run([exe, "-c", prog], capture_output=True, text=True, cwd=d, timeout=1800)

FAIL = set()
def main():
    exe = sys.argv[1]
    pats = gen()
    if len(sys.argv) > 2 and sys.argv[2] == "--count":
        print(len(pats)); return
    CH, bad, tot, ref = 150, 0, 0, 0
    for i in range(0, len(pats), CH):
        c = pats[i:i+CH]
        g = run(exe, c, SUBJ); r = run(sys.executable, c, SUBJ)
        if g.returncode == 90:
            for p in c:
                g1 = run(exe, [p], SUBJ); r1 = run(sys.executable, [p], SUBJ)
                if g1.returncode == 90:
                    ref += 1; continue
                tot += 1
                if (g1.stdout, g1.returncode) != (r1.stdout, r1.returncode):
                    bad += 1; FAIL.add(p)
                    if len(FAIL) <= 12:
                        for a, b in zip(g1.stdout.splitlines(), r1.stdout.splitlines()):
                            if a != b: print("MISMATCH lyp:", a[:240], "\n          cpy:", b[:240]); break
            continue
        tot += len(c)
        gl, rl = g.stdout.splitlines(), r.stdout.splitlines()
        sh = 0
        for a, b in zip(gl, rl):
            if a != b:
                bad += 1; FAIL.add(a.split(" ", 1)[0])
                if sh < 2 and len(FAIL) <= 40:
                    print("MISMATCH lyp:", a[:240], "\n          cpy:", b[:240]); sh += 1
        if len(gl) != len(rl):
            print("LENGTH", len(gl), len(rl), g.returncode, r.returncode, g.stderr[-300:]); bad += 1
    print("patterns %d  refused %d  measured %d  mismatching-rows %d  failing-patterns %d"
          % (len(pats), ref, tot, bad, len(FAIL)))
    open(os.environ.get("FAILOUT", "/dev/null"), "w").write("\n".join(sorted(FAIL)))
main()

