import json, os, shutil, subprocess, sys, tempfile, pathlib

LYP = "/tmp/lyp-adv3-csv/bin/lypning-l"
CORE = "/tmp/lyp-adv3-csv/bin/lypning"
PY = sys.executable

def run(cmd, cwd, stdin_bytes, timeout=10):
    try:
        p = subprocess.run(cmd, cwd=cwd, input=stdin_bytes,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                           timeout=timeout)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired:
        return "TIMEOUT", b"", b""

def setup(cwd, files):
    for name, data in (files or {}).items():
        pth = os.path.join(cwd, name)
        os.makedirs(os.path.dirname(pth), exist_ok=True) if os.path.dirname(name) else None
        with open(pth, "wb") as f:
            f.write(data if isinstance(data, bytes) else data.encode())

def case(prog, files=None, stdin=b"", engine=LYP, timeout=10):
    """returns dict with verdict"""
    res = {}
    for tag, cmd in (("cpython", [PY, "-c", prog]), ("lyp", [engine, "-c", prog])):
        d = tempfile.mkdtemp(prefix="adv3-")
        try:
            setup(d, files)
            res[tag] = run(cmd, d, stdin, timeout)
            # capture post-state of files
            st = {}
            for root, _, fns in os.walk(d):
                for fn in fns:
                    p = os.path.join(root, fn)
                    rel = os.path.relpath(p, d)
                    try:
                        st[rel] = open(p, "rb").read()
                    except Exception:
                        st[rel] = b"<err>"
            res[tag + "_files"] = st
        finally:
            shutil.rmtree(d, ignore_errors=True)
    return res

def verdict(r):
    crc, cout, cerr = r["cpython"]
    lrc, lout, lerr = r["lyp"]
    if lrc == "TIMEOUT":
        return "HANG"
    if crc == "TIMEOUT":
        return "SKIP-cpy-timeout"
    if lrc == 90:
        lines = lerr.decode("utf8", "replace").strip().split("\n")
        if lout != b"":
            return "BAD-refusal-stdout"
        if len(lines) != 1 or ": unsupported: " not in lines[0]:
            return "BAD-refusal-line"
        return "REFUSED"
    if lrc == crc and lout == cout:
        # stderr: for nonzero exit compare last line (exception type/message)
        if crc != 0:
            cl = cerr.decode("utf8","replace").strip().split("\n")
            ll = lerr.decode("utf8","replace").strip().split("\n")
            if cl[-1] != ll[-1]:
                return "DIFF-stderr"
        if r["cpython_files"] != r["lyp_files"]:
            return "DIFF-files"
        return "OK"
    if lrc != crc:
        if lout == cout:
            return "DIFF-rc"
        return "DIFF-rc+out"
