fn collect_self_attrs(body: &[Stmt], out: &mut BTreeSet<String>) {
    fn tgt(t: &Target, out: &mut BTreeSet<String>) {
        match t {
            Target::Attr(_, n) => {
                out.insert(n.to_string());
            }
            Target::Tuple(v) => v.iter().for_each(|x| tgt(x, out)),
            Target::Star(b) => tgt(b, out),
            _ => {}
        }
